d["library_investigation"] = {"start":"found_note","nodes":{"found_note":{"speaker":None,"text":"You pull a book from the shelf. Inside, a folded note: Richardson knew. Monday night. The archive. If you care about the truth, come alone. Your hands shake.","expression":"worried","choices":[{"text":"Keep the note and investigate.","effects":{"flag_found_note":True,"stat_intelligence":5},"next":"note_examine"},{"text":"Someone left this. They know what happened.","effects":{"stat_intelligence":3,"stat_charm":3},"next":"note_think"}]},"note_examine":{"speaker":None,"text":"No name, no initials. But the paper is thick cream-colored with a faint watermark. Something important is hidden here.","expression":"determined","choices":[{"text":"Go to the library again tomorrow.","effects":{"stat_intelligence":3},"next":"end_library"},{"text":"Talk to someone on campus.","effects":{"stat_charm":3},"next":"end_library"}]},"note_think":{"speaker":None,"text":"Someone is warning you. They know Richardson was murdered.","expression":"worried","choices":[{"text":"This could be a trap.","effects":{"stat_intelligence":5},"next":"end_library"},{"text":"I can not ignore this.","effects":{"stat_charm":3},"next":"end_library"}]},"end_library":{"speaker":None,"text":"You slip the note into your pocket. The world tilted off its axis.","expression":"neutral","isEnd":True}}}
