d["campus_walk"]["nodes"]["chloe_approach"] = {"speaker":None,"text":"Chloe is warm, magnetic. But her smile falters.","expression":"smiling","choices":[{"text":"I think you are running a great campaign.","effects":{"relationship_chloe":5},"next":"chloe_greeting"},{"text":"Dr. Richardson was a good man.","effects":{"relationship_chloe":8},"next":"chloe_richardson"}]}
d["campus_walk"]["nodes"]["chloe_greeting"] = {"speaker":"chloe","text":"Oh! Hey! Most people just see posters. But trust is hard to earn.","expression":"smiling","choices":[{"text":"I admire people.","effects":{"relationship_chloe":8,"stat_charm":3},"next":"chloe_end"},{"text":"I need help.","effects":{"relationship_chloe":10},"next":"chloe_secret"}]}
d["campus_walk"]["nodes"]["chloe_richardson"] = {"speaker":"chloe","text":"Richardson was different. He actually cared about students.","expression":"cold","choices":[{"text":"Do you know what happened?","effects":{"relationship_chloe":12},"next":"chloe_richardson_death"},{"text":"He sounds worth remembering.","effects":{"relationship_chloe":8},"next":"chloe_end"}]}
print("build script placeholder")
d["campus_walk"]["nodes"]["chloe_richardson_death"] = {"speaker":"chloe","text":"He is dead. The report says suicide. But I know what people whisper.","expression":"cold","choices":[{"text":"Do you know who killed him?","effects":{"relationship_chloe":15},"next":"chloe_killer"},{"text":"What do you know?","effects":{"relationship_chloe":12},"next":"chloe_killer"}]}
d["campus_walk"]["nodes"]["chloe_killer"] = {"speaker":"chloe","text":"I can not tell you yet. Someone powerful did not want Richardson to speak.","expression":"determined","choices":[{"text":"I want to help uncover the truth.","effects":{"relationship_chloe":15,"flag_trusted_chloe":True},"next":"chloe_end"},{"text":"You will not tell me.","effects":{"relationship_chloe":-3},"next":"chloe_end"}]}
d["campus_walk"]["nodes"]["hana_approach"] = {"speaker":None,"text":"Hana sits in a dim art studio, painting deep reds and blacks.","expression":"neutral","choices":[{"text":"Richardson death must have been difficult.","effects":{"relationship_hana":8},"next":"hana_greeting"},{"text":"Your paintings look intense.","effects":{"relationship_hana":10},"next":"hana_art"}]}
d["campus_walk"]["nodes"]["hana_greeting"] = {"speaker":"hana","text":"Difficult does not cover it. He was the only one who believed in my work.","expression":"quiet_cry","choices":[{"text":"He was important to you.","effects":{"relationship_hana":10},"next":"hana_end"},{"text":"What was he working on?","effects":{"relationship_hana":12,"stat_intelligence":3},"next":"hana_research"}]}

d["campus_walk"]["nodes"]["hana_art"] = {"speaker":"hana","text":"Art is the only language that can say what words can not.","expression":"painting","choices":[{"text":"Show me.","effects":{"relationship_hana":12},"next":"hana_end"},{"text":"What do you see?","effects":{"relationship_hana":8,"stat_intelligence":3},"next":"hana_end"}]}
d["campus_walk"]["nodes"]["hana_research"] = {"speaker":"hana","text":"He was researching something. Digital evidence the university wanted buried.","expression":"stoic","choices":[{"text":"I want to help finish what he started.","effects":{"relationship_hana":15,"flag_trusted_hana":True},"next":"hana_end"},{"text":"What kind of evidence?","effects":{"relationship_hana":12,"stat_intelligence":5},"next":"hana_end"}]}
d["campus_walk"]["nodes"]["maya_approach"] = {"speaker":None,"text":"The CS lab door is locked. Maya ID is still in the slot.","expression":"determined","choices":[{"text":"Wait for Maya.","effects":{"stat_intelligence":2},"next":"maya_greeting"},{"text":"Find what she is hiding.","effects":{"stat_intelligence":5},"next":"maya_sneak"}]}
d["campus_walk"]["nodes"]["maya_greeting"] = {"speaker":"maya","text":"You should not be here. The lab is restricted.","expression":"smirk","choices":[{"text":"Richardson was not suicidal.","effects":{"relationship_maya":10},"next":"maya_response"},{"text":"Can you help me?","effects":{"relationship_maya":12},"next":"maya_response"}]}
d["campus_walk"]["nodes"]["maya_response"] = {"speaker":"maya","text":"I can see every camera. Richardson was meeting someone. But the person wore a mask.","expression":"focused","choices":[{"text":"I need to see that footage.","effects":{"relationship_maya":15,"flag_trusted_maya":True},"next":"maya_end"},{"text":"Who was wearing the mask?","effects":{"relationship_maya":12},"next":"maya_end"}]}
d["campus_walk"]["nodes"]["maya_sneak"] = {"speaker":None,"text":"Maya computer is unlocked. Footage from the night Richardson died. But a second camera shows Chloe ID badge near the archive.","expression":"worried","choices":[{"text":"Chloe was there?","effects":{"stat_intelligence":10,"stat_charm":-3},"next":"maya_sneak_end"},{"text":"Confront Chloe.","effects":{"stat_charm":-3,"stat_intelligence":5},"next":"maya_sneak_end"}]}
d["campus_walk"]["nodes"]["maya_sneak_end"] = {"speaker":"maya","text":"Maya catches you. She does not yell. Now you know why I keep this lab locked. She slides a flash drive.","expression":"afraid","choices":[{"text":"Thank you.","effects":{"relationship_maya":15},"next":"end_day1"}]}
d["campus_walk"]["nodes"]["chloe_end"] = {"speaker":"chloe","text":"I will help, but only if you protect me.","expression":"determined","isEnd":True}
d["campus_walk"]["nodes"]["hana_end"] = {"speaker":"hana","text":"The truth has a price. Are you willing to pay yours?","expression":"stoic","isEnd":True}
d["campus_walk"]["nodes"]["maya_end"] = {"speaker":"maya","text":"The footage does not lie. Justice or safety?","expression":"focused","isEnd":True}
d["campus_walk"]["nodes"]["chloe_secret"] = {"speaker":"chloe","text":"My father received a phone call the night Richardson died. A threatening call.","expression":"tears","choices":[{"text":"I believe you.","effects":{"relationship_chloe":12},"next":"chloe_end"},{"text":"Who called him?","effects":{"relationship_chloe":15},"next":"chloe_end"}]}
d["visit_chloe_office"] = {"start":"chloe_office_start","nodes":{"chloe_office_start":{"speaker":"chloe","text":"Come in. Close the door. I know why you are here. And I know what you have seen.","expression":"cold","choices":[{"text":"I have seen enough to know Richardson was murdered.","effects":{"relationship_chloe":10},"next":"chloe_reveal"},{"text":"I trust you, Chloe.","effects":{"relationship_chloe":12},"next":"chloe_reveal"}]},"chloe_reveal":{"speaker":"chloe","text":"Richardson was blackmailing my father. He had evidence that the university construction contracts were corrupt. My father signed off on them. Richardson had the proof. My father was going to be ruined. So my father arranged for Richardson to be silenced.","expression":"cold","choices":[{"text":"Your father killed Richardson? That is monstrous.","effects":{"relationship_chloe":5,"stat_charm":-5},"next":"chloe_reaction"},{"text":"I believe you, but who carried it out?","effects":{"relationship_chloe":5},"next":"chloe_reaction"}]},"chloe_reaction":{"speaker":"chloe","text":"My father ordered it. But he did not do the dirty work. Someone did. And that someone... I do not know who. I only know that after Richardson died, someone close to him came to me and offered a deal: my father protection and money, if I kept quiet and played my part in the election.","expression":"tears","choices":[{"text":"Who made the deal?","effects":{"relationship_chloe":15},"next":"chloe_deal"},{"text":"I do not think you can trust me.","effects":{"relationship_chloe":-5},"next":"chloe_end"}]},"chloe_deal":{"speaker":"chloe","text":"The person who made the deal... was Hana mentor. The same person who taught Hana how to paint. The same person who is now in her studio, watching her, making sure she does not say anything.","expression":"tears","choices":[{"text":"So Hana is being controlled?","effects":{"relationship_chloe":15,"stat_intelligence":5},"next":"chloe_end"},{"text":"I need to see Hana. This is urgent.","effects":{"relationship_chloe":12},"next":"chloe_end"}]}}}
d["visit_maya_lab"] = {"start":"maya_lab_start","nodes":{"maya_lab_start":{"speaker":"maya","text":"You are back. Good. I have been analyzing the footage. The archive footage is incomplete. Someone edited it. But there is a second copy, unedited, hidden in the server.","expression":"focused","choices":[{"text":"Show me. What does the full picture show?","effects":{"relationship_maya":15},"next":"maya_full_footage"},{"text":"Who edited the footage?","effects":{"relationship_maya":12},"next":"maya_full_footage"}]},"maya_full_footage":{"speaker":"maya","text":"The full footage shows Richardson meeting with Hana mentor — the art professor, Dr. Vance. They were arguing about data. Then Hana enters. She was not supposed to be there. But she was. And she saw everything.","expression":"worried","choices":[{"text":"Hana was there? She knows what happened?","effects":{"relationship_hana":10,"stat_intelligence":5},"next":"maya_conclusion"},{"text":"So Richardson was meeting with Vance.","effects":{"stat_intelligence":5},"next":"maya_conclusion"}]},"maya_conclusion":{"speaker":"maya","text":"The pattern is clear now. Richardson was going to expose corruption in the university research funding. Vance was involved. Hana saw it. And someone made sure Richardson was silenced. But they also made sure Hana stayed quiet. Which one of them is the killer?","expression":"focused","choices":[{"text":"I need to confront the person who killed Richardson.","effects":{"stat_intelligence":5,"stat_charm":3},"next":"maya_conclusion_end"},{"text":"I need to protect Hana. She is in danger.","effects":{"relationship_hana":10},"next":"maya_conclusion_end"}]},"maya_conclusion_end":{"speaker":None,"text":"Maya hands you the unedited footage. This is your weapon. Use it wisely.","expression":"determined","isEnd":True}}}
d["visit_hana_studio"] = {"start":"hana_studio_start","nodes":{"hana_studio_start":{"speaker":"hana","text":"You came back. Good. I have been waiting. There is something you need to see. My latest painting — it is not just art. It is a confession.","expression":"painting","choices":[{"text":"Show me the painting.","effects":{"relationship_hana":15},"next":"hana_painting"},{"text":"What did you see the night Richardson died?","effects":{"relationship_hana":12},"next":"hana_painting"}]},"hana_painting":{"speaker":"hana","text":"This is what I saw. Richardson, arguing with someone in the archive. A figure in the shadows. And then — the painting shows what happened next. The figure grabbed Richardson. Richardson struggled. And then silence. The painting is unfinished because I do not know who the figure was.","expression":"quiet_cry","choices":[{"text":"Maybe it is Vance. Maybe he did it.","effects":{"relationship_hana":15,"stat_intelligence":5},"next":"hana_vance"},{"text":"Maybe it was someone else entirely.","effects":{"relationship_hana":10},"next":"hana_vance"}]},"hana_vance":{"speaker":"hana","text":"Vance is dangerous. He has been watching me. Making sure I do not say anything. He thinks if I stay quiet, he can protect me. But he can not protect me from what I have seen. I have seen the face. And now I have to decide: tell the truth and risk everything, or stay silent and live with it.","expression":"stoic","choices":[{"text":"I will protect you. Tell me everything.","effects":{"relationship_hana":18,"flag_trusted_hana":True},"next":"hana_end"},{"text":"You need to go to the police.","effects":{"relationship_hana":15,"stat_intelligence":5},"next":"hana_end"}]}}}
d["confrontation_preparation"] = {"start":"confrontation_start","nodes":{"confrontation_start":{"speaker":None,"text":"You now have pieces of the puzzle. Maya has the footage. Chloe has the connections. Hana has the eyewitness account. But one of them is hiding the biggest secret of all. Tonight, you face the final choice. Who do you trust?","expression":"determined","choices":[{"text":"I trust Maya and expose the truth with the footage.","effects":{"flag_trusted_maya":True},"next":"ending_maya"},{"text":"I trust Chloe and work within the system.","effects":{"flag_trusted_chloe":True},"next":"ending_chloe"},{"text":"I trust Hana and follow her lead.","effects":{"flag_trusted_hana":True},"next":"ending_hana"},{"text":"I expose everything publicly.","effects":{"flag_exposed_truth":True},"next":"ending_truth"}]},"ending_maya":{"speaker":"maya","text":"Maya presents the footage at the student council meeting. The evidence is undeniable — Richardson was murdered, and Vance was the killer. But when Vance is exposed, Chloe father is also named as an accomplice. The university erupts in scandal. Maya is hailed as a hero, but Chloe campaign is destroyed. You saved the truth but lost the person you trusted most.","expression":"determined","isEnd":True},"ending_chloe":{"speaker":"chloe","text":"Chloe uses her father political connections to quietly remove Vance from the university and bury the scandal. Richardson name is cleared, but the truth never comes out publicly. Chloe wins the election and becomes president. She promises to protect the university from scandal. But you know — the real killer is free. And Chloe is now more powerful than ever.","expression":"tears","isEnd":True},"ending_hana":{"speaker":"hana","text":"Hana reveals the truth through her art — an exhibition that exposes everything. The paintings go viral. Richardson is vindicated. Vance is exposed. But Hana herself is targeted by those she exposed. She disappears from campus. You saved the truth, but the person who told it is gone.","expression":"stoic","isEnd":True},"ending_truth":{"speaker":None,"text":"You publish everything — the footage, the evidence, Hana testimony — to the entire university online. The truth explodes across campus. Richardson is vindicated, Vance is arrested, and Chloe father corruption is exposed. But the fallout is enormous. Maya loses her job. Chloe loses everything. Hana is exposed and targeted. You chose truth over safety. The university will never be the same.","expression":"determined","isEnd":True}}}
